# background ==================================================================

# Here we extract orthologs from emapper output.

# Steps:
# - bf to hs orthologs
#   - get bf to hs orthologs from the bf emapper output (at protein level)
#   - add bf and hs gene ids to this table
#   - only keep the gene id columns and get rid of protein id columns as well as
#     orth_type information (this was likely generated by emapper at the
#     protein level; we will recreate this at the gene level)
#   - keep distinct rows
# - based on the gene_ids, recreate orth_types

# setup =======================================================================
library(tidyverse)
library(here)

bfdir <- here("species/bflo/VNyyK/")
hsdir <- here("species/hsap/genome/GRCh38/113")

# data ========================================================================
bf <- read_tsv(
  here(bfdir, "results/emapper/out/out.emapper.orthologs"),
  comment = "##"
) %>%
  rename(query = `#query`)

bf_genes <- read_tsv(here(bfdir, "results/genes/gid-pid_mapping.tsv"))
hs_genes <- read_csv(here(hsdir, "results/genes/gid-pid-mapping.csv"))

# make column ids consistent for joining
bf_genes <- bf_genes %>%
  rename_with(function(x) paste0("bf_", x))
hs_genes <- hs_genes %>%
  rename_with(function(x) paste0("hs_", x))

# remove gid and pid version numbers for mouse
hs_genes <- hs_genes %>%
  mutate(
    hs_gene_id = str_remove(hs_gene_id, "\\.\\d+"),
    hs_protein_id = str_remove(hs_protein_id, "\\.\\d+")
  )

# bflo to hsap orthologs ======================================================
bf <- bf %>%
  filter(species == "Homo sapiens(9606)") %>%
  # 1 ortholog per row
  mutate(orthologs = str_split(orthologs, ",")) %>%
  unnest(orthologs) %>%
  # clean up
  mutate(orthologs = str_remove(orthologs, "^\\*"))

# add gene ids and remove other columns
bf_to_hs <- bf %>%
  rename(bf_protein_id = query, hs_protein_id = orthologs) %>%
  left_join(
    select(bf_genes, bf_gene_id, bf_protein_id),
    by = "bf_protein_id"
  ) %>%
  filter(!is.na(bf_gene_id)) %>%
  left_join(
    select(hs_genes, hs_gene_id, hs_protein_id),
    by = "hs_protein_id"
  ) %>%
  filter(!is.na(hs_gene_id)) %>%
  select(bf_gene_id, hs_gene_id) %>%
  distinct()

# assign orthology types ======================================================
orth <- bf_to_hs %>%
  nest(.by = bf_gene_id) %>%
  mutate(n_hsap = map_int(data, ~ length(unique(.x$hs_gene_id)))) %>%
  mutate(
    bf_orth_type = case_when(
      n_hsap == 1 ~ "one2one",
      n_hsap > 1 ~ "one2many"
    )
  ) %>%
  unnest(data) %>%
  nest(.by = hs_gene_id) %>%
  mutate(n_bflo = map_int(data, ~ length(unique(.x$bf_gene_id)))) %>%
  mutate(
    hs_orth_type = case_when(
      n_bflo == 1 ~ "one2one",
      n_bflo > 1 ~ "one2many"
    )
  ) %>%
  unnest(data) %>%
  mutate(
    orth_type = case_when(
      bf_orth_type == "one2many" & hs_orth_type == "one2many" ~ "many2many",
      bf_orth_type == "one2many" & hs_orth_type == "one2one" ~ "one2many",
      bf_orth_type == "one2one" & hs_orth_type == "one2many" ~ "many2one",
      bf_orth_type == "one2one" & hs_orth_type == "one2one" ~ "one2one"
    )
  ) %>%
  select(bf_gene_id, hs_gene_id, orth_type)

# add mouse symbols ===========================================================

orth <- left_join(
  orth,
  (hs_genes %>%
    select(hs_gene_id, hs_symbol) %>%
    distinct()),
  by = "hs_gene_id"
)

# write results ===============================================================
write_csv(
  orth,
  here(bfdir, "results/emapper/processed/emapper_orthologs_hsap.csv")
)

# end =========================================================================
